using System;
using System.IO;
using System.Runtime.CompilerServices;

namespace Foca.Metadata.Tests
{
    /// <summary>
    /// Sample documents shared by every target framework. They are generated by <see cref="Fixtures"/>
    /// (which needs Windows-only System.Drawing) and committed under tests/corpus, so the .NET 10
    /// test run on Linux and macOS analyses byte-identical input.
    /// Set FOCA_UPDATE_CORPUS=1 on a net48 run to regenerate them.
    /// </summary>
    internal static class Corpus
    {
        public static string Directory([CallerFilePath] string source = "")
        {
            return Path.GetFullPath(Path.Combine(Path.GetDirectoryName(source), "..", "corpus"));
        }

        public static byte[] Get(string fileName)
        {
            string path = Path.Combine(Directory(), fileName);
#if NETFRAMEWORK
            if (!File.Exists(path) || Environment.GetEnvironmentVariable("FOCA_UPDATE_CORPUS") == "1")
            {
                System.IO.Directory.CreateDirectory(Directory());
                File.WriteAllBytes(path, Generate(fileName));
            }
#endif
            if (!File.Exists(path))
                throw new FileNotFoundException("Corpus file missing; run the net48 tests once to generate it.", path);
            return File.ReadAllBytes(path);
        }

#if NETFRAMEWORK
        private static byte[] Generate(string fileName)
        {
            switch (fileName)
            {
                case "sample.docx": return Fixtures.Docx();
                case "sample.odt": return Fixtures.Odt();
                case "sample.pdf": return Fixtures.Pdf();
                case "sample.svg": return Fixtures.Svg();
                case "sample.rdp": return Fixtures.Rdp();
                case "sample.jpg": return Fixtures.Jpeg();
                case "cyclic-chain.doc": return Fixtures.CyclicOle();
                default: throw new ArgumentOutOfRangeException(nameof(fileName));
            }
        }
#endif
    }
}
